    'legal.fin.title': 'Ketentuan Keuangan & Pembayaran',
    'legal.fin.sub': 'Penagihan, pengembalian dana, penyelesaian kreator, dan laporan keuangan kuartalan · Lihat detail',
    'legal.privacy.title': 'Kebijakan Privasi',
